<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Sản phẩm MobileX</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="/public/assets/css/site.css"></head><body class="bg-slate-950 text-slate-100"><main class="mx-auto max-w-7xl p-5 pt-10"><a href="?page=home" class="text-blue-300">MobileX</a><h1 class="my-5 text-3xl font-bold">Điện thoại & phụ kiện</h1>
<form id="filters" method="get" class="grid gap-3 rounded-xl bg-slate-900 p-4 sm:grid-cols-2 lg:grid-cols-6"><input type="hidden" name="page" value="products"><label>Từ khóa<input id="search" name="q" value="<?= $e($_GET['q']??'') ?>" class="mt-1 w-full rounded bg-slate-800 p-2" autocomplete="off"><div id="suggestions" class="absolute z-10 bg-slate-800"></div></label><label>Hãng<select name="brand" class="mt-1 w-full rounded bg-slate-800 p-2"><option value="">Tất cả</option><?php foreach($brands as $b): ?><option value="<?= $e($b['slug']) ?>" <?= ($_GET['brand']??'')===$b['slug']?'selected':'' ?>><?= $e($b['name']) ?></option><?php endforeach ?></select></label><label>Danh mục<select name="category" class="mt-1 w-full rounded bg-slate-800 p-2"><option value="">Tất cả</option><?php foreach($categories as $c): ?><option value="<?= $e($c['slug']) ?>" <?= ($_GET['category']??'')===$c['slug']?'selected':'' ?>><?= $e($c['name']) ?></option><?php endforeach ?></select></label><label>Giá từ<input type="number" min="0" name="min" value="<?= $e($_GET['min']??'') ?>" class="mt-1 w-full rounded bg-slate-800 p-2"></label><label>Giá đến<input type="number" min="0" name="max" value="<?= $e($_GET['max']??'') ?>" class="mt-1 w-full rounded bg-slate-800 p-2"></label><label>RAM / storage / accessory<input name="attribute" value="<?= $e($_GET['attribute']??'') ?>" placeholder="256GB, 8GB" class="mt-1 w-full rounded bg-slate-800 p-2"></label><label>Sắp xếp<select name="sort" class="mt-1 w-full rounded bg-slate-800 p-2"><option value="newest">Mới nhất</option><option value="price_asc" <?= ($_GET['sort']??'')==='price_asc'?'selected':'' ?>>Giá tăng dần</option><option value="price_desc" <?= ($_GET['sort']??'')==='price_desc'?'selected':'' ?>>Giá giảm dần</option><option value="name" <?= ($_GET['sort']??'')==='name'?'selected':'' ?>>Tên</option></select></label><button class="rounded bg-blue-600 p-2 font-bold">Lọc sản phẩm</button></form>
<div class="my-4 flex items-center justify-between"><span><?= count($products) ?> sản phẩm</span><button id="compare" class="rounded bg-emerald-700 px-4 py-2">So sánh đã chọn (tối đa 3)</button></div><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4" id="product-grid">
<?php foreach($products as $p): ?><article class="rounded-xl bg-slate-900 p-4"><label class="text-sm"><input type="checkbox" class="compare-item" value="<?= (int)$p['id'] ?>"> So sánh</label><a href="?page=detail&amp;product_id=<?= (int)$p['id'] ?>" class="block"><div class="my-3 flex h-44 items-center justify-center rounded bg-slate-800"><?php if($p['image']): ?><img class="max-h-40" src="<?= $e($p['image']) ?>" alt="<?= $e($p['name']) ?>"><?php else: ?><span class="text-5xl">📱</span><?php endif ?></div><h2 class="font-bold"><?= $e($p['name']) ?></h2></a><p class="text-sm text-slate-400"><?= $e($p['brand']??'') ?> · <?= $e($p['category']??'') ?></p><p class="my-2 text-lg font-bold text-blue-300"><?= number_format((float)$p['price'],0,',','.') ?> ₫ <small class="text-slate-400">· <?= (int)$p['variant_count'] ?> phiên bản</small></p><p class="text-sm <?= (int)$p['stock']?'text-emerald-300':'text-red-300' ?>"><?= (int)$p['stock']?'Còn hàng: '.(int)$p['stock']:'Hết hàng' ?></p><a class="mt-3 inline-block rounded bg-slate-700 px-3 py-2" href="?page=detail&amp;product_id=<?= (int)$p['id'] ?>">Xem chi tiết</a></article><?php endforeach ?>
</div><?php if(!$products): ?><p class="mt-8 text-slate-400">Chưa có sản phẩm phù hợp.</p><?php endif ?></main><script>
document.querySelector('#compare').onclick=()=>{const ids=[...document.querySelectorAll('.compare-item:checked')].map(x=>x.value);if(ids.length<2||ids.length>3){alert('Chọn từ 2 đến 3 sản phẩm để so sánh.');return}location.href='?page=compare&'+ids.map(x=>'id[]='+encodeURIComponent(x)).join('&')};
const input=document.querySelector('#search'), box=document.querySelector('#suggestions');let timer;input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{if(input.value.length<2){box.innerHTML='';return}try{const r=await fetch('?page=search-suggestions&q='+encodeURIComponent(input.value));const rows=await r.json();box.innerHTML=rows.map(p=>`<a class="block p-2 hover:bg-slate-700" href="?page=detail&product_id=${p.id}">${p.name}</a>`).join('')}catch{}},250)});
</script></body></html>
